```python
"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
from collections import deque
import heapq

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


# ----------- Internal helper: Dijkstra -----------
def _dijkstra(graph: WeightedGraph, source: int, target: Optional[int] = None):
    """Return (dist, prev) using Dijkstra; optionally stop when target is finalized."""
    nodes = graph.nodes
    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0.0

    heap = [(0.0, source)]
    visited = set()

    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:  # stale entry
            continue
        if u in visited:
            continue
        visited.add(u)

        if target is not None and u == target:
            break

        for v, w in graph.neighbors(u):
            if v in visited:
                continue
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    return dist, prev


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Now: O((V+E) log V) using a priority queue.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist, prev = _dijkstra(graph, source, target)

    if dist[target] == float('inf'):
        return None, []

    # Reconstruct path
    path = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Now: single Dijkstra pass — O((V+E) log V).
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist, prev = _dijkstra(graph, source)

    # Memoized path reconstruction to avoid repeated work
    path_cache: Dict[int, List[int]] = {source: [source]}

    def build_path(n: int) -> Optional[List[int]]:
        if n in path_cache:
            return path_cache[n]
        if prev[n] is None:
            return None
        p = build_path(prev[n])
        if p is None:
            return None
        path_cache[n] = p + [n]
        return path_cache[n]

    result: Dict[int, Tuple[float, List[int]]] = {}
    for n in nodes:
        if dist[n] != float('inf'):
            path = build_path(n)
            if path is not None:
                result[n] = (dist[n], path)
    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Now: Early-termination Dijkstra — O((V+E) log V), often much less.
    """
    if k <= 0:
        return []
    nodes = graph.nodes
    if source not in nodes:
        return []

    dist: Dict[int, float] = {source: 0.0}
    heap = [(0.0, source)]
    visited = set()
    result: List[Tuple[int, float]] = []

    while heap and len(result) < k:
        d, u = heapq.heappop(heap)
        if u in visited:
            continue
        visited.add(u)

        if u != source:
            result.append((u, d))
            if len(result) >= k:
                break

        for v, w in graph.neighbors(u):
            if v in visited:
                continue
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(heap, (nd, v))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Now: BFS — O(V + E).
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False
    if source == target:
        return True

    visited = {source}
    q = deque([source])

    while q:
        u = q.popleft()
        for v, _ in graph.neighbors(u):
            if v == target:
                return True
            if v not in visited:
                visited.add(v)
                q.append(v)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Now: single DFS/BFS over undirected adjacency — O(V + E).
    """
    nodes = graph.nodes
    # Build undirected adjacency
    undirected: Dict[int, Set[int]] = {n: set() for n in nodes}
    for e in graph._edges:
        undirected[e.src].add(e.dst)
        undirected[e.dst].add(e.src)

    visited: Set[int] = set()
    components: List[Set[int]] = []

    for node in nodes:
        if node in visited:
            continue
        comp = set()
        stack = [node]
        visited.add(node)

        while stack:
            u = stack.pop()
            comp.add(u)
            for v in undirected[u]:
                if v not in visited:
                    visited.add(v)
                    stack.append(v)

        components.append(comp)

    return components
```

✅ **Complexities now match targets:**
- `shortest_path`: **O((V+E) log V)**
- `all_shortest_paths`: **O((V+E) log V)**
- `k_nearest`: **O((V+E) log V)** with early stopping
- `is_reachable`: **O(V+E)**
- `connected_components`: **O(V+E)**

All public APIs (signatures, return types, behaviors) are preserved.
